labs.solution:
UNAVAILABLE = 'The assistant is temporarily unavailable. Please try again in a few minutes.'


class CircuitBreaker:
    def __init__(self, threshold, cooldown):
        self.threshold, self.cooldown = threshold, cooldown
        self.state = 'closed'
        self.failures = 0
        self.opened_at = None

    def allow(self, now):
        if self.state == 'closed':
            return True
        if self.state == 'open' and now - self.opened_at >= self.cooldown:
            self.state = 'half_open'
            return True
        return False

    def record_success(self):
        self.state, self.failures, self.opened_at = 'closed', 0, None

    def record_failure(self, now):
        if self.state == 'half_open':
            self.state, self.opened_at = 'open', now
            return
        self.failures += 1
        if self.failures >= self.threshold:
            self.state, self.opened_at = 'open', now


def call_with_fallbacks(request, chain, breakers, now):
    for name, fn in chain:
        breaker = breakers[name]
        if not breaker.allow(now):
            continue
        try:
            result = fn(request)
        except Exception:
            breaker.record_failure(now)
            continue
        breaker.record_success()
        return name, result
    return 'unavailable', UNAVAILABLE

import math


def run_cascade(request, cheap, capable, validate, min_confidence):
    first = cheap(request)
    if first['confidence'] >= min_confidence and validate(first['output']):
        return {'output': first['output'], 'escalated': False, 'cost': first['cost']}
    second = capable(request)
    return {'output': second['output'], 'escalated': True, 'cost': first['cost'] + second['cost']}


def cost_per_successful_task(records):
    successes = sum(1 for r in records if r['success'])
    if successes == 0:
        return math.inf
    return sum(r['cost'] for r in records) / successes

